import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { useQuery } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The session lives in the URL: `user` is the signed-in name (no password), `sheet` the active
// sheet id. Every feature that works per sheet or records who did something reads these.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// `today` is the sheet's own date (yyyy-mm-dd). Every date decision and every default date in the
// app uses it — never the browser's or server's clock.
export type Sheet = { id: string; today: string };
export const sheetKey = (id: string) => ['sheet', id] as const;

export const loadSheet = (id: string) => postJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}/load`, {});

/** The active sheet, as the store holds it (filled by the sheet picker when it loads a sheet). */
export function useSheet() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetKey(sheet ?? ''),
    queryFn: () => loadSheet(sheet!),
    enabled: !!sheet,
    staleTime: Infinity,
  });
}

/** The active sheet's today (yyyy-mm-dd): use it for every date default and date decision. */
export const useSheetToday = () => useSheet().data?.today;
import { useState } from 'react';
import type { FormEvent } from 'react';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
